double root_newton_raphson_var_1(double (*f)(double), double x0, double tol, int max_iter) {
    double x = x0;
    for (int iter = 0; iter < max_iter; iter++) {
        double fx = f(x);
        if (fabs(fx) < tol) return x;
        double dfx = (f(x + 1e-7) - f(x - 1e-7)) / 2e-7;
        if (fabs(dfx) < 1e-12) break;
        x -= fx / dfx;
    }
    return x;
}

